import pytest
from solution import to_roman, from_roman

@pytest.mark.parametrize('n,s', [(1,'I'),(4,'IV'),(9,'IX'),(14,'XIV'),(40,'XL'),(90,'XC'),(400,'CD'),(1994,'MCMXCIV'),(3999,'MMMCMXCIX')])
def test_roundtrip(n, s):
    assert to_roman(n) == s
    assert from_roman(s) == n

@pytest.mark.parametrize('bad', [0, 4000, -1])
def test_range(bad):
    with pytest.raises(ValueError):
        to_roman(bad)

@pytest.mark.parametrize('bad', ['IIII', 'IC', 'ABC', ''])
def test_invalid(bad):
    with pytest.raises(ValueError):
        from_roman(bad)
